#!/bin/zsh
# S3d — same-terminal rework law: resume session 01a019e7, visible window.
# The packet is the only scope authority; this script carries no file list.
set -u
MISSION="/Users/vladmihaimiron/Documents/DebateAIRO/dialectical-engine"
REL="docs/missions/2026-08-17-accounts-privacy-security"
PACKET="${REL}/logs/S3d-packet.md"
LOG="${MISSION}/${REL}/logs/S3-codex.log"
cd "${MISSION}" || exit 1
[[ -f "${MISSION}/${PACKET}" ]] || { print "REFUSING: packet ${PACKET} missing" | tee -a "${LOG}"; exit 1; }
if pgrep -f "codex exec" >/dev/null 2>&1; then print "REFUSING: codex alive" | tee -a "${LOG}"; exit 1; fi

GOAL="/goal S3d: mail channel + verification cooldown, the LAST of the VR-9 split. S3a, S3b and S3c are CLOSED and dual-greenlit at commits cff3dd5 and b2324d6 — do not touch their work. Read ${PACKET} in full; it is your only scope authority. Read the ticket's accumulated comments first, because several of these defects were found by lenses reviewing OTHER tickets and handed to you. WHAT S3C ALREADY DID FOR YOU: it moved the per-address bound onto the OUTBOUND send as a row-level 20-minute spacing giving 3 mails per rolling hour, written inside prepareVerificationResend's transaction at packages/db/src/identity.ts:415-417 — that is the shape old blocker B3 asked for and it is dual-greenlit, so confirm the cooldown is genuinely written in the token-minting transaction and re-measure the 3/hour ceiling, then LEAVE IT ALONE. FOUR BLOCKERS. D1: apps/api/src/registration.ts:370 holds pendingMailDispatches as an unbounded Set, measured at 100/200/300/400 entries and climbing under a hanging transport, each retained entry holding plaintext email, the RAW VERIFICATION TOKEN, and the raw source IP. The raw token is the sharp part — everywhere else the token is stored only as verification_token_hash, but here the working credential itself sits in process memory for as long as a slow or hung MTA keeps the promise alive, with no bound on accumulation, so anyone with heap access via a core dump, a memory-disclosure bug or a debugger gets live verification links. Bound the structure with a ruled maximum concurrent in-flight dispatch count — what happens at the bound is your design, refuse or queue with a cap or shed, but it must be deliberate and must not lose an account or silently drop a promised mail. Minimise the retained payload so the raw token does not outlive the send attempt and plaintext email and raw IP do not sit in a process-local structure longer than the dispatch needs them; if a retry needs a token, re-derive or re-read it rather than holding it. Prove it on the real stack: with a hanging transport, drive sustained registrations and show in-flight dispatches stay at the ruled bound and RSS plateaus, and walk the object graph to show ZERO raw tokens retained outside an active send. D2: prepareVerificationResend ROTATES verification_token_hash on every send at identity.ts:415-416, and both lenses measured the consequence — under attack the owner CAN complete verification but NOT with the token they hold, because only the newest mailed token works and the older link returns VERIFICATION_TOKEN_INVALID. S3c bounded the RATE to the ruled 3/hour so it is no worse than ruled, but it was explicitly deferred to you and the property is wrong: a third party who names an address can invalidate a link the rightful owner is holding. The property to reach is that a person who received a verification link can use it and nobody else's actions can take that away. How you get there is your design — resending the same token until it expires, honouring the previous token for a window, or another shape — but state the reasoning and consider the case rotation was presumably protecting against, a token believed leaked; if the two goals genuinely conflict, say so with the trade rather than picking silently. Prove it: owner registers and holds link A, an attacker triggers the full 3/hour of resends, and link A STILL VERIFIES. D3: the first email must not ship a dead link. The historical defect is that the resend UPDATE rotated the token hash BEFORE the registration mail was dispatched, so the user's first email arrived already invalid. S3c reshaped this path, so REPRODUCE AGAINST CURRENT CODE FIRST, RED or not, and state plainly whether it is still live — if fixed, prove it and say which change fixed it; if live, fix it and prove register-then-immediate-resend leaves the first link valid or deliberately superseded, never silently dead. D4: a failed delivery record must not permanently disable the cooldown. Historically dispatchVerification swallowed record failures so one failure left verification_last_sent_at NULL forever and the cooldown inert for that account. Re-check on current code: if a delivery record fails, is the cooldown still enforced on the next attempt? A cooldown a single transient error disables permanently is a rate-limit bypass with no alarm. Prove it by injecting a delivery-record failure, showing the cooldown still holds afterwards and that the failure is audited with a correlation id, never the email and never the raw IP or UA. ALSO FOLD IN: delivery honesty — when mail genuinely cannot be sent, what does the user learn and what does the operator learn? A promised email that never arrives with no operator signal is the S3b lesson in a different place. Do NOT leak whether the address exists; coordinate with S3b's equal-work property, which is dual-greenlit and must not regress. And confirm rather than rewrite SendmailMailSender, which already validates recipient shape, rejects CRLF, passes -- before the recipient and kills on timeout — if you find a genuine injection or argument-smuggling hole, that IS a finding, say so with a repro. VR-10 STANDING RULE: mutation-test every security assertion, show each goes RED, include the evidence. THREE tickets running have shipped assertions that could not fail for their believed reason — S3c's two headline flood proofs passed against a limiter with NO rate limiting at all because they saturated first and then asserted refusal. Before submitting, ask of each assertion: what state would make this pass for the wrong reason? PROOF DISCIPLINE: real stack, production policy parameters, no harness that suppresses the effect under test, thresholds derived from a measured null rather than chosen because the achievable result clears them. T9 t_6ff49601 is NOT yours — the resend deadlock surfacing as an untyped 500 and reopening the address-existence oracle is separately ticketed and pre-existing; do not touch it. Append progress lines to ${REL}/logs/S3d-progress.log. Do NOT commit or push. Post READY FOR PEER REVIEW when all gates pass."

PROMPTFILE="$(mktemp -t codex-s3d)"
print -r -- "${GOAL}" > "${PROMPTFILE}"
osascript <<APPLESCRIPT >/dev/null
tell application "Terminal"
  do script "printf '\\\\033]0;CODEX S3d\\\\007'; cd '${MISSION}'; echo '=== S3d — Codex (resume 01a019e7) ==='; echo '(this window IS the seat — closing it stops the rework)'; echo; { echo \\"=== S3d starting \$(date -u +%FT%TZ) ===\\"; codex exec resume 01a019e7-e36f-7131-b509-5dcb8d52b8b6 -c model='\\"gpt-5.6-sol\\"' -c model_reasoning_effort='\\"xhigh\\"' -c sandbox_mode='\\"danger-full-access\\"' \\"\$(cat '${PROMPTFILE}')\\" </dev/null 2>&1; echo \\"=== S3d exited \$(date -u +%FT%TZ) ===\\"; } | tee -a '${LOG}'; rm -f '${PROMPTFILE}'"
  activate
end tell
APPLESCRIPT
print "launched S3d in a visible Terminal window; log: ${LOG}"
